test('lineVat handles different VAT rates', () => {
  const line21 = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 };
  const line9 = { qty: 100, unitPrice: 1000, vatRate: 9, discountPercent: 0 };
  const line0 = { qty: 100, unitPrice: 1000, vatRate: 0, discountPercent: 0 };
  assert.equal(lineVat(line21), 21000);
  assert.equal(lineVat(line9), 9000);
  assert.equal(lineVat(line0), 0);
});

test('lineVat rounds per line', () => {
  const line = { qty: 3, unitPrice: 100, vatRate: 21, discountPercent: 0 };
  const vat = 300 * 21 / 100;
  assert.equal(lineVat(line), 63);
});

test('invoiceTotals includes VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 100, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 178500);
  assert.equal(totals.total, 1028500);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 100, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 850000;
  const discount = 85000;
  const amount = 765000;
  const vat = 160650;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 100, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, unitPrice: 37, name: 'Printed flyer A4 (each)', vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 1, unitPrice: 60000, name: 'Brand workshop (day, VAT exempt)', vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Vat = 178500;
  const line2Vat = 333;
  const line3Vat = 0;
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
});

test('invoiceTotals clamps negative values at zero', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 100, name: 'Design work (hour)', vatRate: 21, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});
